use ttlcache::TtlCache;

#[test]
fn test_basic_insert_get() {
    let mut cache: TtlCache<&str, i32> = TtlCache::new();
    cache.insert("a", 1, 100);
    assert_eq!(cache.get("a", 50), Some(&1)); // not expired at t=50
}

#[test]
fn test_expired_get() {
    let mut cache: TtlCache<&str, i32> = TtlCache::new();
    cache.insert("a", 1, 100);
    assert_eq!(cache.get("a", 150), None); // expired at t=150
}

#[test]
fn test_missing_key() {
    let cache: TtlCache<&str, i32> = TtlCache::new();
    assert_eq!(cache.get("x", 0), None);
}

#[test]
fn test_remove_expired() {
    let mut cache: TtlCache<&str, i32> = TtlCache::new();
    cache.insert("a", 1, 10);
    cache.insert("b", 2, 12);
    cache.insert("c", 3, 30);
    cache.remove_expired(15); // removes a (expires_at=10) and b (expires_at=12)
    assert_eq!(cache.get("a", 15), None);
    assert_eq!(cache.get("b", 15), None);
    assert_eq!(cache.get("c", 15), Some(&3));
}

#[test]
fn test_overwrite() {
    let mut cache: TtlCache<&str, i32> = TtlCache::new();
    cache.insert("a", 1, 10);
    cache.insert("a", 2, 100); // overwrite with longer TTL
    assert_eq!(cache.get("a", 50), Some(&2));
}

